from pipeline.training_metrics import (CheckpointGate, macro_standard_error,
                                       pooled_standard_error, RETENTION_Z, SELECTION_Z)

K = 4
# family -> (cases, correct draws /180-or-144, native draws). Seed 1111 dev,
# sft/best.json, as used by training/tests/test_gate_admission.py. Case counts
# are the real ones from the Step 0 read: 45x6 + 36x1 = 306.
DEV = {"base64": (45, 157/180, 0/180), "collections": (45, 169/180, 157/180),
       "enum": (45, 174/180, 174/180), "heapq": (45, 162/180, 151/180),
       "statistics": (36, 137/144, 137/144), "textwrap": (45, 159/180, 159/180),
       "unicodedata": (45, 165/180, 41/180)}
CONTROL = {"base64", "unicodedata"}
FAMS = sorted(DEV)


# ---- latent case model: p_c = sigmoid(mu + sigma z), calibrated to (mean, ICC)
_GH_X, _GH_W = np.polynomial.hermite_e.hermegauss(64)
_GH_W = _GH_W / _GH_W.sum()

def _moments(mu, sigma):
    p = 1.0 / (1.0 + np.exp(-(mu + sigma * _GH_X)))
    m = float(_GH_W @ p)
    v = float(_GH_W @ (p - m) ** 2)
    return m, v

def calibrate(mean, icc):
    """(mu, sigma) with E[p]=mean and Var(p)=icc*mean*(1-mean)."""
    if mean <= 1e-9 or mean >= 1 - 1e-9 or icc <= 0:
        return (math.log(max(mean, 1e-9) / max(1 - mean, 1e-9)) if 1e-9 < mean < 1 - 1e-9
                else (-40.0 if mean <= 1e-9 else 40.0)), 0.0
    target = icc * mean * (1 - mean)
    lo, hi = 0.0, 40.0
    for _ in range(80):                     # bisect sigma; mu re-solved each time
        sigma = 0.5 * (lo + hi)
        a, b = -60.0, 60.0
        for _ in range(80):                 # bisect mu so E[p] == mean
            mu = 0.5 * (a + b)
            if _moments(mu, sigma)[0] < mean: a = mu
            else: b = mu
        if _moments(mu, sigma)[1] < target: lo = sigma
        else: hi = sigma
    return mu, sigma


class World:
    """Per-case latent correctness and native-given-correct, one ICC."""
    def __init__(self, icc):
        self.par = {}
        for f, (m, pc, pn) in DEV.items():
            self.par[f] = (m, calibrate(pc, icc), calibrate(pn / pc if pc else 0.0, icc))

    def latents(self, rng):
        return {f: (rng.standard_normal(m), rng.standard_normal(m))
                for f, (m, _, _) in self.par.items()}

    def arm(self, rng, z, carry, lift_correct=0.0, lift_native=0.0):
        """Per-case draw counts for one checkpoint sharing case latents `z`."""
        out = {}
        for f, (m, (mc, sc), (mn, sn)) in self.par.items():
            zc, zn = z[f]
            if carry < 1.0:
                w = math.sqrt(max(0.0, 1 - carry * carry))
                zc = carry * zc + w * rng.standard_normal(m)
                zn = carry * zn + w * rng.standard_normal(m)
            pc = np.clip(1 / (1 + np.exp(-(mc + sc * zc))) + lift_correct, 0, 1)
            add = lift_native if f not in CONTROL else 0.0
            pn = np.clip(1 / (1 + np.exp(-(mn + sn * zn))) + add, 0, 1)
            c = rng.binomial(K, pc)
            out[f] = (c, rng.binomial(c, pn))     # native capped at correct
        return out


def metrics_of(counts):
    def over(keys):
        cs = [counts[f][0].sum() / (K * len(counts[f][0])) for f in keys]
        ns = [counts[f][1].sum() / (K * len(counts[f][0])) for f in keys]
        return {"correct": sum(cs) / len(cs), "correct_native": sum(ns) / len(ns),
                "draws": sum(K * len(counts[f][0]) for f in keys)}
    per = {f: over([f]) for f in counts}
    return dict(over(FAMS), by_family=per, by_capability=per,
                by_population={"coverage": over([f for f in FAMS if f not in CONTROL]),
                               "fallback-control": over([f for f in FAMS if f in CONTROL])})


# ---- the proposed estimator: cluster-robust SE of the PAIRED macro difference
def clustered_macro_diff_se(base, cand, idx, keys=None):
    keys = keys or FAMS
    total = 0.0
    for f in keys:
        d = (cand[f][idx] - base[f][idx]) / K       # per-case difference of means
        m = len(d)
        if m < 2:
            raise ValueError("a family with one case cannot carry a variance")
        total += float(d.var(ddof=1)) / m
    return math.sqrt(total) / len(keys)


class ProposedGate(CheckpointGate):
    """Shipped rule, same shape, two repairs: the SE is of the paired
    difference and is clustered at the case, and retention is too."""
    def set_pair(self, base_counts):
        self.base_counts = base_counts
    def observe_pair(self, step, counts):
        m = metrics_of(counts)
        self.margin = self.z * clustered_macro_diff_se(self.base_counts, counts, 1)
        self._pair = counts
        self.observe(step, m)
    def _retention(self, metrics):
        lost = []
        slices = {"coverage": [f for f in FAMS if f not in CONTROL],
                  "fallback-control": [f for f in FAMS if f in CONTROL]}
        for name, fams in slices.items():
            se = clustered_macro_diff_se(self.base_counts, self._pair, 0, fams)
            allowed = max(self.tolerance, RETENTION_Z * se)
            base = self.baseline["by_population"][name]["correct"]
            obs = metrics["by_population"][name]["correct"]
            if obs < base - allowed:
                lost.append({"population": name, "allowed_drop": allowed})
        return lost


def run(rule, icc, carry, lift_c, lift_n, trials=4000, seed=7, steps=1, noisy_base=True):
    rng = np.random.default_rng(seed)
    world = World(icc)
    admitted = 0
    margins, ses = [], []
    for _ in range(trials):
        z = world.latents(rng)
        base = world.arm(rng, z, carry) if noisy_base else world.arm(rng, z, 1.0)
        bm = metrics_of(base)
        if rule == "proposed":
            g = ProposedGate(baseline=bm); g.set_pair(base)
        else:
            g = CheckpointGate(baseline=bm)
            if rule == "shipped_sqrt2":
                g.margin *= math.sqrt(2)
            elif rule == "no_margin":
                g.margin = 0.0
        for s in range(1, steps + 1):
            cand = world.arm(rng, z, carry, lift_c, lift_n)
            if rule == "proposed":
                g.observe_pair(25 * s, cand)
            else:
                g.observe(25 * s, metrics_of(cand))
        margins.append(g.margin)
        admitted += g.best_step != 0
    return admitted / trials, float(np.mean(margins))

