        n1=round(p*n_cases); return [1.0]*n1+[0.0]*(n_cases-n1)
    if model=="beta":   # moderate clustering
        conc=2.0
        if p<=0 or p>=1: return [p]*n_cases
        return [rng.betavariate(p*conc,(1-p)*conc) for _ in range(n_cases)]
    raise ValueError

def build(model, k, seed):
    rng=random.Random(seed)
    spec={}
    for fam,(n,c,nn) in DEV.items():
        nc=n//4
        pc,pn = c/n, nn/n
        rc=case_rates(nc,pc,model,rng)
        rn=case_rates(nc,pn,model,rng)
        rn=[min(a,b) for a,b in zip(rn,rc)]
        spec[fam]=(nc,rc,rn)
    return spec

def draw(spec,k,rng):
    out={}
    for fam,(nc,rc,rn) in spec.items():
        cc=0; nn=0
        for i in range(nc):
            for _ in range(k):
                ok = rng.random()<rc[i]
                if ok:
                    cc+=1
                    if rng.random() < (rn[i]/rc[i] if rc[i] else 0.0): nn+=1
        out[fam]=(nc*k,cc,nn)
    return out

def run(model,k,trials=1500,seed=7):
    spec=build(model,k,seed)
    rng=random.Random(seed+1)
    base=metrics_of(draw(spec,k,rng))   # baseline itself is a draw
    adm=0
    for _ in range(trials):
        g=CheckpointGate(baseline=base)
        g.observe(25, metrics_of(draw(spec,k,rng)))
        adm += g.best_step==25
    return adm/trials, g.margin

