CONC = 1.0/ICC - 1.0   # alpha+beta for a beta-binomial with this ICC at k=4

def q(rng, p):
    if p <= 0.0 or p >= 1.0: return p
    return rng.betavariate(CONC*p, CONC*(1.0-p))

def draw_arm(rng, props, lift_native=0.0):
    """props: {family: [(qc, qn_given_c), ...] per case} -> counts dict."""
    out = {}
    for f,(n,c,nn) in T.DEV.items():
        pc = c/n
        pn = min(pc, nn/n + (lift_native if f not in T.CONTROL else 0.0))
        ratio = pn/pc if pc else 0.0
        cc = nc = 0
        for (uc, un) in props[f]:
            # uc, un are uniform case-level quantiles shared across arms
            qc = q(random.Random(hash((f,'c',uc))), pc)
            qn = q(random.Random(hash((f,'n',un))), ratio)
            k = 4
            ci = sum(rng.random() < qc for _ in range(k))
            cc += ci
            nc += sum(rng.random() < qn for _ in range(ci))
        out[f] = (n, cc, nc)
    return out

def props_for(rng):
    return {f: [(rng.random(), rng.random()) for _ in range(n//4)] for f,(n,c,nn) in T.DEV.items()}

def run(trials, seed, noisy_baseline, rho, lift_native=0.0):
    rng = random.Random(seed); ok = 0; used = 0
    for _ in range(trials):
        pb = props_for(rng)
        pc_ = {f: [pb[f][i] if rng.random() < rho else (rng.random(), rng.random())
                   for i in range(len(pb[f]))] for f in pb}
        base = T.metrics_of(draw_arm(rng, pb, 0.0)) if noisy_baseline else T.metrics_of(T.DEV)
        try: g = CheckpointGate(baseline=base)
        except Exception: continue
        used += 1
        g.observe(25, T.metrics_of(draw_arm(rng, pc_, lift_native)))
        ok += g.best_step == 25
    return ok/used

