# family -> (draws, correct_draws, native_draws) exactly as tests/test_gate_admission.py DEV
DEV = {
    "base64": (180, 157, 0), "collections": (180, 169, 157), "enum": (180, 174, 174),
    "heapq": (180, 162, 151), "statistics": (144, 137, 137), "textwrap": (180, 159, 159),
    "unicodedata": (180, 165, 41),
}
CONTROL = {"base64", "unicodedata"}
DRAWS_PER_CASE = 4
CASES = {f: n // DRAWS_PER_CASE for f, (n, _, _) in DEV.items()}   # 45x6 + 36 = 306

# ---------------------------------------------------------------- latent model
_GRID = [(-6.0 + 12.0 * i / 400.0) for i in range(401)]
_W = [math.exp(-0.5 * z * z) for z in _GRID]
_WSUM = sum(_W)


def _moments(mu, sigma):
    """E[q], E[q^2] for q = sigmoid(mu + sigma z), z ~ N(0,1)."""
    m1 = m2 = 0.0
    for z, w in zip(_GRID, _W):
        q = 1.0 / (1.0 + math.exp(-(mu + sigma * z)))
        m1 += w * q
        m2 += w * q * q
    return m1 / _WSUM, m2 / _WSUM


def _solve_mu(p, sigma):
    lo, hi = -40.0, 40.0
    for _ in range(80):
        mid = 0.5 * (lo + hi)
        if _moments(mid, sigma)[0] < p:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)


def solve_latent(p, rho):
    """(mu, sigma) with mean p and intra-case correlation rho = Var(q)/(p(1-p))."""
    if p <= 0.0 or p >= 1.0 or rho <= 0.0:
        return (_solve_mu(min(max(p, 1e-9), 1 - 1e-9), 0.0), 0.0)
    lo, hi = 0.0, 30.0
    for _ in range(60):
        sigma = 0.5 * (lo + hi)
        mu = _solve_mu(p, sigma)
        m1, m2 = _moments(mu, sigma)
        got = (m2 - m1 * m1) / (p * (1.0 - p))
        if got < rho:
            lo = sigma
        else:
            hi = sigma
    sigma = 0.5 * (lo + hi)
    return (_solve_mu(p, sigma), sigma)


class Split:
    """The dev split's parameters: per family, a correctness latent and a
    native-given-correct latent, both with intra-case correlation `rho`."""

    def __init__(self, rho, lift_correct=0.0, lift_native=0.0):
        self.rho = rho
        self.params = {}
        for f, (n, c, nn) in DEV.items():
            pc = min(1.0, c / n + lift_correct)
            pn = min(pc, nn / n + (lift_native if f not in CONTROL else 0.0))
            r = (pn / pc) if pc > 0 else 0.0
            self.params[f] = (solve_latent(pc, rho), solve_latent(r, rho), pc, r)

    def target_macro(self):
        cor = sum(p[2] for p in self.params.values()) / len(self.params)
        nat = sum(p[2] * p[3] for p in self.params.values()) / len(self.params)
        return cor, nat


def _q(latent, z):
    mu, sigma = latent
    if sigma == 0.0:
        return 1.0 / (1.0 + math.exp(-mu)) if -700 < mu < 700 else (1.0 if mu > 0 else 0.0)
    x = mu + sigma * z
    if x > 700:
        return 1.0
    if x < -700:
        return 0.0
    return 1.0 / (1.0 + math.exp(-x))


def case_latents(rng):
    """One standard-normal pair per case, SHARED by every checkpoint: a case is
    intrinsically easy or hard and every checkpoint meets the same case."""
    return {f: [(rng.gauss(0, 1), rng.gauss(0, 1)) for _ in range(CASES[f])] for f in DEV}


def _binom4(rng, k, p):
    if p <= 0.0:
        return 0
    if p >= 1.0:
        return k
    return sum(rng.random() < p for _ in range(k))


def draw_eval(rng, split, latents):
    """One evaluation: per family, per case, (correct_draws, native_draws)."""
    out = {}
    for f, cases in latents.items():
        (lc, ln, _, _) = split.params[f]
        rows = []
        for (zc, zn) in cases:
            c = _binom4(rng, DRAWS_PER_CASE, _q(lc, zc))
            nat = _binom4(rng, c, _q(ln, zn))
            rows.append((c, nat))
        out[f] = rows
    return out


# ---------------------------------------------------------------- metrics dict
def metrics_of(ev):
    """`summarize`-shaped metrics from per-case counts (validated in check.py)."""
    def over(keys):
        tot = sum(DRAWS_PER_CASE * len(ev[k]) for k in keys)
        return {"correct": sum(sum(c for c, _ in ev[k]) / (DRAWS_PER_CASE * len(ev[k])) for k in keys) / len(keys),
                "correct_native": sum(sum(n for _, n in ev[k]) / (DRAWS_PER_CASE * len(ev[k])) for k in keys) / len(keys),
                "draws": tot}
    per = {f: over([f]) for f in ev}
    cov = [f for f in ev if f not in CONTROL]
    con = [f for f in ev if f in CONTROL]
    return dict(over(list(ev)), by_family=per, by_capability=per,
                by_population={"coverage": over(cov), "fallback-control": over(con)})


# ---------------------------------------------------------------- selection rules
def sidak_z(alpha, k):
    """Phi^-1((1-alpha)^(1/k)) -- the one-sided Sidak critical value."""
    target = (1.0 - alpha) ** (1.0 / k)
    lo, hi = 0.0, 10.0
    for _ in range(80):
        mid = 0.5 * (lo + hi)
        if 0.5 * (1.0 + math.erf(mid / math.sqrt(2.0))) < target:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)


def paired_macro_delta(base_ev, cand_ev):
    """Macro delta of correct-and-native and its case-clustered standard error.

    The macro is a mean over families of a mean over that family's per-case
    deltas, and cases are the independent unit: SE^2 = (1/F^2) * sum_f s_f^2/c_f.
    Pairing removes the case-difficulty variance component; clustering by case
    is what the 4-draws-per-case design requires.
    """
    fams = sorted(base_ev)
    deltas, var = [], 0.0
    for f in fams:
        d = [(cn - bn) / float(DRAWS_PER_CASE)
             for (_, bn), (_, cn) in zip(base_ev[f], cand_ev[f])]
        c = len(d)
        m = sum(d) / c
        s2 = sum((x - m) ** 2 for x in d) / (c - 1) if c > 1 else 0.0
        # Floor: at least one case moving one draw, so a family that happens to
        # move in lockstep cannot report zero noise.
        s2 = max(s2, (1.0 / DRAWS_PER_CASE) ** 2 / c)
        deltas.append(m)
        var += s2 / c
    f_n = len(fams)
    return sum(deltas) / f_n, math.sqrt(var) / f_n


def eligible(baseline, metrics, tolerance=0.02):
    """Gate A and retention, exactly as CheckpointGate applies them."""
    if metrics["correct"] < baseline["correct"] - tolerance:
        return False
    for name, base in baseline["by_population"].items():
        allowed = max(tolerance, 3.0 * pooled_standard_error(base))
        got = metrics["by_population"][name]["correct"]
        if got < base["correct"] - allowed:
            return False
    return True
